CREATE TABLE el_students(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,photo TEXT NOT NULL DEFAULT '',birth_date TEXT NOT NULL DEFAULT '',gender TEXT NOT NULL DEFAULT '',national_id TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',school TEXT NOT NULL DEFAULT '',grade TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL DEFAULT '',emergency_contact TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('new','active','inactive','suspended','graduated','withdrawn','pending')),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,code),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_guardians(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',user_id TEXT REFERENCES el_users(id),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_student_guardians(org_id TEXT NOT NULL,student_id TEXT NOT NULL,guardian_id TEXT NOT NULL,relationship TEXT NOT NULL DEFAULT 'guardian',PRIMARY KEY(student_id,guardian_id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,guardian_id) REFERENCES el_guardians(org_id,id));
CREATE TABLE el_teachers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',qualification TEXT NOT NULL DEFAULT '',specialization TEXT NOT NULL DEFAULT '',experience INTEGER NOT NULL DEFAULT 0 CHECK(experience>=0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),notes TEXT NOT NULL DEFAULT '',user_id TEXT REFERENCES el_users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,code),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_teacher_branches(org_id TEXT NOT NULL,teacher_id TEXT NOT NULL,branch_id TEXT NOT NULL,PRIMARY KEY(teacher_id,branch_id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TRIGGER el_teacher_home AFTER INSERT ON el_teachers BEGIN INSERT INTO el_teacher_branches(org_id,teacher_id,branch_id) VALUES(NEW.org_id,NEW.id,NEW.branch_id); END;
CREATE TABLE el_courses(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',subject TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL DEFAULT '',grade TEXT NOT NULL DEFAULT '',curriculum TEXT NOT NULL DEFAULT '',duration INTEGER NOT NULL DEFAULT 12 CHECK(duration>0),sessions INTEGER NOT NULL DEFAULT 12 CHECK(sessions>0),price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0),capacity INTEGER NOT NULL DEFAULT 30 CHECK(capacity>0),registration_start TEXT NOT NULL DEFAULT '',registration_end TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','archived')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,code),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_course_branches(org_id TEXT NOT NULL,course_id TEXT NOT NULL,branch_id TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),PRIMARY KEY(course_id,branch_id),FOREIGN KEY(org_id,course_id) REFERENCES el_courses(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TRIGGER el_course_home AFTER INSERT ON el_courses BEGIN INSERT INTO el_course_branches(org_id,course_id,branch_id,price) VALUES(NEW.org_id,NEW.id,NEW.branch_id,NEW.price); END;
CREATE TABLE el_classrooms(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,floor TEXT NOT NULL DEFAULT '',capacity INTEGER NOT NULL DEFAULT 30 CHECK(capacity>0),equipment TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','maintenance')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,branch_id,code),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_groups(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,course_id TEXT NOT NULL,teacher_id TEXT NOT NULL,classroom_id TEXT NOT NULL,assistant_id TEXT,capacity INTEGER NOT NULL DEFAULT 20 CHECK(capacity>0),start_date TEXT NOT NULL,end_date TEXT NOT NULL,session_minutes INTEGER NOT NULL DEFAULT 90 CHECK(session_minutes BETWEEN 15 AND 480),price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','completed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,code),CHECK(end_date>=start_date),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,course_id) REFERENCES el_courses(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id),FOREIGN KEY(org_id,classroom_id) REFERENCES el_classrooms(org_id,id));
CREATE TRIGGER el_group_integrity_insert BEFORE INSERT ON el_groups BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_classrooms WHERE id=NEW.classroom_id AND branch_id=NEW.branch_id AND status='active' AND capacity>=NEW.capacity) THEN RAISE(ABORT,'Room unavailable or capacity exceeded') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_teacher_branches tb JOIN el_teachers t ON t.id=tb.teacher_id WHERE tb.teacher_id=NEW.teacher_id AND tb.branch_id=NEW.branch_id AND t.status='active') THEN RAISE(ABORT,'Teacher not assigned to this branch') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_course_branches cb JOIN el_courses c ON c.id=cb.course_id WHERE cb.course_id=NEW.course_id AND cb.branch_id=NEW.branch_id AND c.status='active') THEN RAISE(ABORT,'Course not assigned to this branch') END;
END;
CREATE TABLE el_enrollments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,student_id TEXT NOT NULL,group_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','waiting','withdrawn','transferred','completed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,group_id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,group_id) REFERENCES el_groups(org_id,id));
CREATE TRIGGER el_enrollment_capacity BEFORE INSERT ON el_enrollments WHEN NEW.status='active' BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_students s JOIN el_groups g ON g.id=NEW.group_id WHERE s.id=NEW.student_id AND s.org_id=NEW.org_id AND s.branch_id=g.branch_id AND s.status IN ('active','new') AND g.status='active') THEN RAISE(ABORT,'Student and active group must share a branch') END;
SELECT CASE WHEN (SELECT count(*) FROM el_enrollments WHERE group_id=NEW.group_id AND status='active')>=(SELECT capacity FROM el_groups WHERE id=NEW.group_id) THEN RAISE(ABORT,'Group is full') END;
END;
CREATE TRIGGER el_enrollment_update_capacity BEFORE UPDATE OF status ON el_enrollments WHEN NEW.status='active' AND OLD.status<>'active' BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_students s JOIN el_groups g ON g.id=NEW.group_id WHERE s.id=NEW.student_id AND s.branch_id=g.branch_id AND s.status IN ('active','new') AND g.status='active') THEN RAISE(ABORT,'Student and active group must share a branch') END;
SELECT CASE WHEN (SELECT count(*) FROM el_enrollments WHERE group_id=NEW.group_id AND status='active')>=(SELECT capacity FROM el_groups WHERE id=NEW.group_id) THEN RAISE(ABORT,'Group is full') END;
END;
CREATE TABLE el_transfers(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,student_id TEXT NOT NULL,from_branch TEXT NOT NULL,to_branch TEXT NOT NULL,requested_by TEXT NOT NULL REFERENCES el_users(id),approved_by TEXT REFERENCES el_users(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(from_branch<>to_branch),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,from_branch) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,to_branch) REFERENCES el_branches(org_id,id));
CREATE INDEX el_students_branch ON el_students(org_id,branch_id,status);
CREATE INDEX el_guardians_branch ON el_guardians(org_id,branch_id);
CREATE INDEX el_teachers_branch ON el_teachers(org_id,branch_id);
CREATE INDEX el_courses_branch ON el_courses(org_id,branch_id);
CREATE INDEX el_groups_branch ON el_groups(org_id,branch_id,status);
CREATE INDEX el_enrollments_group ON el_enrollments(group_id,status);
CREATE INDEX el_transfers_org ON el_transfers(org_id,status);
CREATE TRIGGER el_group_integrity_update BEFORE UPDATE ON el_groups BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_classrooms WHERE id=NEW.classroom_id AND branch_id=NEW.branch_id AND status='active' AND capacity>=NEW.capacity) THEN RAISE(ABORT,'Room unavailable or capacity exceeded') END;
SELECT CASE WHEN (SELECT count(*) FROM el_enrollments WHERE group_id=OLD.id AND status='active')>NEW.capacity THEN RAISE(ABORT,'Group is full') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_teacher_branches tb JOIN el_teachers t ON t.id=tb.teacher_id WHERE tb.teacher_id=NEW.teacher_id AND tb.branch_id=NEW.branch_id AND t.status='active') THEN RAISE(ABORT,'Teacher not assigned to this branch') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_course_branches cb JOIN el_courses c ON c.id=cb.course_id WHERE cb.course_id=NEW.course_id AND cb.branch_id=NEW.branch_id AND c.status='active') THEN RAISE(ABORT,'Course not assigned to this branch') END;
END;
CREATE TRIGGER el_course_price AFTER UPDATE OF price ON el_courses BEGIN UPDATE el_course_branches SET price=NEW.price WHERE course_id=NEW.id AND branch_id=NEW.branch_id; END;
CREATE TRIGGER el_room_capacity BEFORE UPDATE OF capacity ON el_classrooms BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM el_groups WHERE classroom_id=OLD.id AND status='active' AND capacity>NEW.capacity) THEN RAISE(ABORT,'Room unavailable or capacity exceeded') END; END;
CREATE TRIGGER el_transfer_guard BEFORE UPDATE OF status ON el_transfers BEGIN
SELECT CASE WHEN OLD.status<>'pending' OR NOT EXISTS(SELECT 1 FROM el_students WHERE id=OLD.student_id AND branch_id=OLD.from_branch) THEN RAISE(ABORT,'Transfer is no longer pending') END;
END;
